INSERT INTO `site_settings` (`id`, `key`, `value`, `type`, `group`, `label`, `createdAt`, `updatedAt`) VALUES ('cmlux3uab000h20sdahj83nlc', 'about_history', 'The hospital was established by Italian invaders in 1930 E.C. The Hospital has been serving as the only public specialized Mental hospital since 1930 E.C. In addition to providing clinical service, the hospital has been delivering different types of long-term and short-term training for health professionals.', 'text', 'about', 'Hospital History', '2026-02-20 13:20:30', '2026-03-25 07:47:54');
