INSERT INTO `categories` (`id`, `name`, `slug`, `color`, `createdAt`) VALUES ('cmlux3v74000s20sdlfy65ybd', 'Health Tips', 'health-tips', '#4682B4', '2026-02-20 13:20:32');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `featuredImage`, `type`, `status`, `authorId`, `categoryId`, `tags`, `views`, `isFeatured`, `metaTitle`, `metaDesc`, `publishedAt`, `eventDate`, `eventLocation`, `gallery`, `externalId`, `createdAt`, `updatedAt`) VALUES ('cmlux3wl9001a20sdeu5ts7dq', 'EMSH Conducts Intensive Mental Health Training for Community Health Workers', 'community-health-worker-training-program', 'Over 120 community health workers from across Addis Ababa attended a three-day intensive training at EMSH, covering early detection, crisis management, and referral protocols for mental health conditions.', '<p>Emmanuel Mental Specialized Hospital recently completed a landmark training initiative that equipped over 120 community health workers (CHWs) from Addis Ababa sub-cities with the knowledge and skills to identify and respond to mental health crises at the community level.</p><p>The three-day intensive program, conducted in both Amharic and English, covered critical topics including early symptom recognition, suicide risk assessment, anti-stigma communication, and clear referral pathways to EMSH''s outpatient department.</p><h3>Training Program Highlights:</h3><ul><li><strong>134 participants</strong> from 10 sub-cities trained</li><li>Modules on schizophrenia, bipolar disorder, and substance use</li><li>Practical crisis de-escalation role-play exercises</li><li>Certification awarded to all successful graduates</li></ul><p>This program is part of EMSH''s broader community mental health integration strategy, working in partnership with the Addis Ababa City Health Bureau to decentralize mental health support.</p><p>`This training will enable us to reach patients who would otherwise never make it to a hospital,` said the lead facilitator from EMSH''s Community Psychiatry Department.</p>', 'https://images.unsplash.com/photo-1582213782179-e0d53f98f2ca?auto=format&fit=crop&q=80&w=1200', 'NEWS', 'PUBLISHED', 'cmlux3st9000020sdshmhqif9', NULL, '[`training`,`community`,`health-workers`,`outreach`]', 2, 0, NULL, NULL, '2026-02-12 07:30:00', NULL, NULL, NULL, NULL, '2026-02-20 13:20:33', '2026-03-06 10:23:58');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `featuredImage`, `type`, `status`, `authorId`, `categoryId`, `tags`, `views`, `isFeatured`, `metaTitle`, `metaDesc`, `publishedAt`, `eventDate`, `eventLocation`, `gallery`, `externalId`, `createdAt`, `updatedAt`) VALUES ('cmmeqyq8n0003dj0exioaexja', 'Addressing the Digital Age: Understanding Social Media Addiction in Modern Ethiopia', 'understanding-social-media-addiction-impact', 'As social media becomes central to youth life, behavioral addictions are on the rise. Our clinical teams discuss the Dopamine-driven patterns, psychological symptoms, and strategic steps for digital detoxification.', '
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `featuredImage`, `type`, `status`, `authorId`, `categoryId`, `tags`, `views`, `isFeatured`, `metaTitle`, `metaDesc`, `publishedAt`, `eventDate`, `eventLocation`, `gallery`, `externalId`, `createdAt`, `updatedAt`) VALUES ('cmmeqyqh10005dj0ea2agppcx', 'A Century of Care: EMSH''s Continuing Legacy in Mental Health Pioneerism', 'emsh-legacy-90-years', 'Established in 1930 E.C. (1938 G.C.), Emmanuel Mental Specialized Hospital remains the primary pillar for psychiatric care in Ethiopia, serving millions through specialized treatments and research.', '<p>Emmanuel Mental Specialized Hospital (EMSH) stands as Ethiopia''s foremost and oldest specialized institution dedicated exclusively to mental health care. Established in 1930 E.C., the hospital has served as a cornerstone of psychiatric services for over nine decades.</p><p>Our comprehensive services include specialized psychiatry, clinical psychology, world-class rehabilitation, and community-based outreach. As we move forward, we remain committed to our founding motto: `ßêêßèáßèÑßê¥ßê« ßîñßèô ßèÑßèòßë¦ßîïßêêßèò!` (Working together for mental health).</p>', 'https://images.unsplash.com/photo-1538108149393-fdfd816944fd?auto=format&fit=crop&q=80&w=1200', 'NEWS', 'PUBLISHED', 'cmlux3st9000020sdshmhqif9', NULL, NULL, 2, 0, NULL, NULL, '2026-02-20 14:30:00', NULL, NULL, NULL, NULL, '2026-03-06 10:23:58', '2026-03-07 17:00:29');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `featuredImage`, `type`, `status`, `authorId`, `categoryId`, `tags`, `views`, `isFeatured`, `metaTitle`, `metaDesc`, `publishedAt`, `eventDate`, `eventLocation`, `gallery`, `externalId`, `createdAt`, `updatedAt`) VALUES ('cmmeqyqmt0007dj0ef14q7omr', 'Understanding Depression: Symptoms, Causes, and When to Seek Help', 'understanding-depression-symptoms-causes', 'Depression is one of the most misunderstood mental health conditions. EMSH clinical experts explain the difference between sadness and clinical depression, and how modern treatments offer a path to recovery.', '<p>Depression (Ye''Hibet Beshita GÇô ßï¿ßêÉßïÿßèò ßêàßêÿßê¥) is more than just feeling sad. It is a serious medical condition that affects how a person thinks, feels, and functions in daily life. At Emmanuel Mental Specialized Hospital, depression is one of the most commonly treated psychiatric conditions.</p><h3>Common Symptoms of Depression:</h3><ul><li>Persistent sadness or feelings of emptiness lasting more than two weeks</li><li>Loss of interest in activities once enjoyed (anhedonia)</li><li>Changes in appetite and sleep patterns</li><li>Fatigue, low energy, and difficulty concentrating</li><li>Feelings of worthlessness or excessive guilt</li><li>In severe cases: thoughts of self-harm or suicide</li></ul><h3>Effective Treatments Available at EMSH:</h3><ul><li><strong>Pharmacotherapy:</strong> Antidepressant medications tailored to individual patient profiles</li><li><strong>Cognitive Behavioural Therapy (CBT):</strong> Evidence-based talk therapy to reshape negative thinking patterns</li><li><strong>Group Therapy:</strong> Peer support sessions facilitated by licensed clinical psychologists</li><li><strong>Community Follow-up:</strong> Outreach teams to support patients after discharge</li></ul><p>If you or someone you know is experiencing these symptoms for more than two weeks, please reach out. Early treatment leads to faster recovery. <strong>ßêêßèáßèÑßê¥ßê« ßîñßèô ßèÑßèòßë¦ßîïßêêßèò!</strong></p>', 'https://images.unsplash.com/photo-1527689368864-3a821dbccc34?auto=format&fit=crop&q=80&w=1200', 'NEWS', 'PUBLISHED', 'cmlux3st9000020sdshmhqif9', NULL, NULL, 0, 0, NULL, NULL, '2026-02-17 08:00:00', NULL, NULL, NULL, NULL, '2026-03-06 10:23:58', '2026-03-06 10:23:58');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `featuredImage`, `type`, `status`, `authorId`, `categoryId`, `tags`, `views`, `isFeatured`, `metaTitle`, `metaDesc`, `publishedAt`, `eventDate`, `eventLocation`, `gallery`, `externalId`, `createdAt`, `updatedAt`) VALUES ('cmmeqyqws000bdj0eveg0nugj', 'World Mental Health Day 2025: EMSH Leads Nationwide Awareness Drive', 'world-mental-health-day-2025-awareness', 'On World Mental Health Day, October 10, 2025, EMSH spearheaded a nationwide awareness campaign across schools, universities, and media platforms under the theme `Mental Health is a Human Right.`', '<p>On October 10, 2025, Emmanuel Mental Specialized Hospital marked World Mental Health Day with a comprehensive nationwide awareness campaign. Under the global theme <em>`Mental Health is a Universal Human Right,`</em> the hospital organized a series of events designed to reduce stigma and promote access to mental health services for all Ethiopians.</p><h3>Key Activities:</h3><ul><li><strong>Public Symposium:</strong> A major conference held at EMSH bringing together policymakers, clinicians, researchers, and civil society organizations</li><li><strong>University Outreach:</strong> Clinical teams visited 8 universities across Addis Ababa, reaching over 5,000 students</li><li><strong>Radio & TV Campaigns:</strong> Educational spots broadcast on ETV and FM stations in Amharic and Afaan Oromo</li><li><strong>Free Consultations:</strong> Walk-in mental health screening offered free of charge at EMSH for the entire week</li></ul><p>Dr. [Medical Director] remarked: `Every Ethiopian deserves access to quality mental health care. Today is a reminder that mental health is not a luxury GÇö it is a fundamental human right. Our doors are always open.`</p><p>EMSH treated over 800 walk-in patients during the free consultation week, demonstrating the enormous unmet need for mental health services in the country.</p>', 'https://images.unsplash.com/photo-1593113598332-cd288d649433?auto=format&fit=crop&q=80&w=1200', 'NEWS', 'PUBLISHED', 'cmlux3st9000020sdshmhqif9', NULL, NULL, 0, 1, '', NULL, '2026-03-06 10:40:23', NULL, NULL, NULL, NULL, '2026-03-06 10:23:59', '2026-03-06 10:40:23');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `featuredImage`, `type`, `status`, `authorId`, `categoryId`, `tags`, `views`, `isFeatured`, `metaTitle`, `metaDesc`, `publishedAt`, `eventDate`, `eventLocation`, `gallery`, `externalId`, `createdAt`, `updatedAt`) VALUES ('cmmeqyr15000ddj0e5om1mzh0', 'New Neuropsychiatry Research Unit Opens at EMSH, Advancing Brain Science in Africa', 'neuropsychiatry-research-unit-launch', 'EMSH has officially inaugurated its dedicated Neuropsychiatry Research Unit, a state-of-the-art facility for studying the biological basis of psychiatric disorders GÇö a first of its kind in Ethiopia.', '<p>Emmanuel Mental Specialized Hospital has taken a landmark step in advancing psychiatric science in Africa with the inauguration of its new dedicated <strong>Neuropsychiatry Research Unit</strong>. The unit, equipped with modern neuroimaging support systems, EEG facilities, and a clinical trials coordination center, represents a major investment in evidence-based mental health understanding for the region.</p><p>The unit will focus on research areas critical to Ethiopia''s mental health landscape, including:</p><ul><li><strong>Genetic and biomarker studies</strong> in schizophrenia and bipolar disorder</li><li><strong>Neurological co-morbidities</strong> in psychiatric patients</li><li><strong>Pharmacogenomics:</strong> personalizing medication for Ethiopian patient populations</li><li><strong>Epilepsy and psychiatric comorbidity</strong> management protocols</li></ul><p>In its first year, the unit aims to publish at least 10 peer-reviewed papers in collaboration with international academic partners, including institutions in Europe and North America.</p><p>`Ethiopian patients deserve treatments developed with their biology in mind,` said the Head of the Research Department. `This unit is our first step toward that future.`</p><p>The facility will also serve as a training ground for the next generation of psychiatric researchers in Ethiopia, offering postgraduate research fellowships.</p>', 'https://images.unsplash.com/photo-1559757148-5c350d0d3c56?auto=format&fit=crop&q=80&w=1200', 'ANNOUNCEMENT', 'PUBLISHED', 'cmlux3st9000020sdshmhqif9', NULL, NULL, 0, 0, '', '', '2026-03-06 13:24:24', NULL, NULL, '[]', NULL, '2026-03-06 10:23:59', '2026-03-06 13:24:24');
INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `featuredImage`, `type`, `status`, `authorId`, `categoryId`, `tags`, `views`, `isFeatured`, `metaTitle`, `metaDesc`, `publishedAt`, `eventDate`, `eventLocation`, `gallery`, `externalId`, `createdAt`, `updatedAt`) VALUES ('cmmeqyr45000fdj0ef85gj3g6', 'Caring for Caregivers: EMSH Launches Support Program for Families of Psychiatric Patients', 'caregiver-support-program-launch', 'Recognizing the mental burden on families, EMSH has launched a structured caregiver support and education program GÇö providing free counseling, psychoeducation, and peer support groups every Saturday.', '<p>Mental illness does not only affect the individual GÇö it profoundly impacts entire families. Addressing this often-overlooked dimension of mental health, Emmanuel Mental Specialized Hospital has officially launched its <strong>Caregiver Support and Psychoeducation Program</strong>, offering structured support to families and loved ones of psychiatric patients.</p><h3>Program Components:</h3><ul><li><strong>Weekly Psychoeducation Sessions:</strong> Every Saturday, 9:00 AM GÇô 11:00 AM, at the EMSH Outpatient Compound. Topics include understanding diagnosis, medication management, crisis prevention, and handling relapses.</li><li><strong>Free Family Counseling:</strong> Up to four free individual counseling sessions with a licensed clinical psychologist</li><li><strong>Peer Support Groups:</strong> Facilitated groups connecting families who are navigating similar challenges</li><li><strong>Mental Health First Aid Training:</strong> Teaching families how to safely respond to a psychiatric emergency at home</li></ul><p>The program is free of charge and open to all families of current and former EMSH patients. Registration is done at the Outpatient Department reception desk.</p><p>`A family that understands mental illness is a family that can heal together,` said the program coordinator. `We want caregivers to feel seen, supported, and equipped.`</p>', 'https://images.unsplash.com/photo-1573497620053-ea5300f94f21?auto=format&fit=crop&q=80&w=1200', 'NEWS', 'PUBLISHED', 'cmlux3st9000020sdshmhqif9', NULL, NULL, 0, 1, '', '', '2026-03-06 13:25:06', NULL, NULL, '[]', NULL, '2026-03-06 10:23:59', '2026-03-06 13:25:06');
