INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES ('cmlux3wq9001c20sdwjiz0j4q', 'What are your working hours?', 'Our outpatient services operate Monday to Friday from 2:30 AM to 10:00 AM. Emergency services are available 24/7.', NULL, 2, 1, '2026-02-20 13:20:34', '2026-02-20 13:20:34');
INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES ('cmlux3wtk001d20sdewgrgnqq', 'Is there emergency psychiatric care?', 'Yes, our emergency psychiatric services are available 24 hours a day, 7 days a week. Call 991 for immediate assistance.', NULL, 3, 1, '2026-02-20 13:20:34', '2026-02-20 13:20:34');
INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES ('cmlux3x31001e20sdqga0mpue', 'Do you offer CPD training for health professionals?', 'Yes, AMSH offers various CPD training programs for healthcare professionals. Visit our CPD page to see upcoming courses and register.', NULL, 4, 1, '2026-02-20 13:20:34', '2026-02-20 13:20:34');
INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES ('cmlux3xb2001f20sdrm0t9w8m', 'Can I submit research for review?', 'Yes, researchers can submit their work through our Research page. All submissions are reviewed by our expert panel.', NULL, 5, 1, '2026-02-20 13:20:34', '2026-02-20 13:20:34');
INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES ('cmlux3xho001g20sdxvgzpv38', 'Are services free or paid?', 'As a public government hospital, AMSH provides services at subsidized rates. Emergency services are always provided regardless of ability to pay.', NULL, 6, 1, '2026-02-20 13:20:35', '2026-02-20 13:20:35');
INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES ('cmmd6qdol00068sjohedbj1bx', 'Do you accept international insurance?', 'Yes, we work with several international insurance providers. Please contact our billing office for details.', 'Billing', 1, 1, '2026-03-05 08:09:50', '2026-03-05 08:09:50');
INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES ('cmmd6qdol00078sjor8e7nwxq', 'Is parking available at the hospital?', 'Yes, we have a dedicated parking lot for patients and visitors available 24/7.', 'General', 3, 1, '2026-03-05 08:09:50', '2026-03-05 08:09:50');
INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES ('cmmd75tcx0006toode2uxtzbn', 'Do you accept international insurance?', 'Yes, we work with several international insurance providers. Please contact our billing office for details.', 'Billing', 1, 1, '2026-03-05 08:21:50', '2026-03-05 08:21:50');
